export function flipTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate =
    side === "top"
      ? "rotateX(-20deg)"
      : side === "bottom"
        ? "rotateX(20deg)"
        : side === "left"
          ? "rotateY(20deg)"
          : "rotateY(-20deg)";
  return `perspective(500px) ${rotate} scale(0.8)`;
}

export function uprightTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate = side === "left" || side === "right" ? "rotateY(0deg)" : "rotateX(0deg)";
  return `perspective(500px) ${rotate} scale(1)`;
}

"use client";

import * as React from "react";
import { useInView, type Transition } from "motion/react";

export const entranceSpring: Transition = {
  type: "spring",
  stiffness: 200,
  damping: 20,
};

export const heightSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 30,
  bounce: 0,
  restDelta: 0.01,
};

export const highlightSpring: Transition = {
  type: "spring",
  stiffness: 500,
  damping: 40,
};

export const fadeTween: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

export const softEase = [0.23, 1, 0.32, 1] as const;

export type SlideDirection = "up" | "down" | "left" | "right";

const HOVER_QUERY = "(hover: hover) and (pointer: fine)";
const COARSE_QUERY = "(pointer: coarse)";

function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(false);

  React.useEffect(() => {
    const mql = window.matchMedia(query);
    const update = () => setMatches(mql.matches);
    update();
    mql.addEventListener("change", update);
    return () => mql.removeEventListener("change", update);
  }, [query]);

  return matches;
}

export function useCanHover() {
  return useMediaQuery(HOVER_QUERY);
}

export function useCoarsePointer() {
  return useMediaQuery(COARSE_QUERY);
}

export function useMounted() {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => setMounted(true), []);
  return mounted;
}

export function useInViewEffect(
  ref: React.RefObject<Element | null>,
  enabled: boolean,
  once: boolean,
  margin: string,
) {
  const inView = useInView(ref, {
    once,
    amount: 0.35,
    margin: margin as `${number}px`,
  });
  return enabled ? inView : true;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function mergeRefs<T>(
  ...refs: Array<React.Ref<T> | undefined>
): React.RefCallback<T> {
  return (node) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === "function") ref(node);
      else (ref as React.MutableRefObject<T | null>).current = node;
    }
  };
}

"use client";

import * as React from "react";
import { motion, type Transition } from "motion/react";
import { cn } from "@/lib/utils";
import { useTempoTransition } from "../motion";
import { highlightSpring, useCanHover } from "./shared";

type HighlightContextValue = {
  id: string;
  active: string | null;
  setActive: (value: string | null) => void;
  hover: boolean;
  click: boolean;
  disabled: boolean;
  transition: Transition;
  className?: string;
  activeClassName?: string;
  style?: React.CSSProperties;
  canHover: boolean;
};

const HighlightContext = React.createContext<HighlightContextValue | null>(null);

export function useHighlight() {
  const context = React.useContext(HighlightContext);
  if (!context) throw new Error("useHighlight must be used inside Highlight");
  return context;
}

export type HighlightProps = {
  children: React.ReactNode;
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null) => void;
  hover?: boolean;
  click?: boolean;
  disabled?: boolean;
  className?: string;
  activeClassName?: string;
  style?: React.CSSProperties;
  transition?: Transition;
};

export function Highlight({
  children,
  value,
  defaultValue = null,
  onValueChange,
  hover = false,
  click = true,
  disabled = false,
  className,
  activeClassName = "bg-background shadow-sm",
  style,
  transition,
}: HighlightProps) {
  const id = React.useId();
  const [internal, setInternal] = React.useState<string | null>(defaultValue);
  const controlled = value !== undefined;
  const active = controlled ? value : internal;
  const canHover = useCanHover();
  const spring = useTempoTransition(transition ?? highlightSpring);

  React.useEffect(() => {
    if (defaultValue !== null) setInternal(defaultValue);
  }, [defaultValue]);

  const setActive = React.useCallback(
    (next: string | null) => {
      if (disabled) return;
      if (!controlled) setInternal(next);
      onValueChange?.(next);
    },
    [controlled, disabled, onValueChange],
  );

  const context = React.useMemo<HighlightContextValue>(
    () => ({
      id,
      active,
      setActive,
      hover,
      click,
      disabled,
      transition: spring,
      className,
      activeClassName,
      style,
      canHover,
    }),
    [
      active,
      activeClassName,
      canHover,
      className,
      click,
      disabled,
      hover,
      id,
      setActive,
      spring,
      style,
    ],
  );

  return (
    <HighlightContext.Provider value={context}>
      <div
        data-slot="highlight"
        className={cn("relative", className)}
        style={style}
      >
        {children}
      </div>
    </HighlightContext.Provider>
  );
}

export type HighlightItemProps = {
  children: React.ReactNode;
  value: string;
  disabled?: boolean;
  className?: string;
  activeClassName?: string;
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onPointerEnter?: React.PointerEventHandler<HTMLDivElement>;
  onPointerLeave?: React.PointerEventHandler<HTMLDivElement>;
};

export function HighlightItem({
  children,
  value,
  disabled,
  className,
  activeClassName,
  onClick,
  onPointerEnter,
  onPointerLeave,
}: HighlightItemProps) {
  const context = useHighlight();
  const isActive = context.active === value;
  const isDisabled = disabled ?? context.disabled;
  const interactiveHover = context.hover && context.canHover;

  const handleClick = (event: React.MouseEvent<HTMLDivElement>) => {
    onClick?.(event);
    if (isDisabled) return;
    if (!interactiveHover && context.click) context.setActive(value);
  };

  const handleEnter = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerEnter?.(event);
    if (isDisabled) return;
    if (interactiveHover) context.setActive(value);
  };

  const handleLeave = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerLeave?.(event);
    if (isDisabled) return;
    if (interactiveHover && context.active === value) context.setActive(null);
  };

  return (
    <div
      data-slot="highlight-item"
      data-active={isActive ? "true" : "false"}
      data-value={value}
      onClick={handleClick}
      onPointerEnter={handleEnter}
      onPointerLeave={handleLeave}
      className={cn("relative", className)}
    >
      {isActive && !isDisabled && (
        <motion.span
          aria-hidden="true"
          layoutId={`highlight-surface-${context.id}`}
          transition={context.transition}
          className={cn(
            "pointer-events-none absolute inset-0 z-0",
            activeClassName ?? context.activeClassName,
          )}
          style={context.style}
        />
      )}
      <span className="relative z-[1]">{children}</span>
    </div>
  );
}
